     1	package hotel.documents;
     2	
     3	import hotel.reservations.Guest;
     4	import hotel.reservations.Identification;
     5	import hotel.reservations.PriceCalculator;
     6	import hotel.reservations.Reservation;
     7	import hotel.rooms.Room;
     8	import hotel.rooms.RoomType;
     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	
    12	/**
    13	 * The document the guest gets when the reservation is confirmed, at check-out, and on request. Which one it
    14	 * is depends on how the guest is identified: the receipt (CPF), the lodging invoice (company) or the booking
    15	 * receipt (passport). The fields that do not apply to the kind of document are null.
    16	 */
    17	public record ReservationReceipt(
    18	        String title,
    19	        long reservationId,
    20	        String guestName,
    21	        String guestCpf,
    22	        String companyCnpj,
    23	        String companyName,
    24	        String guestPassport,
    25	        String guestCountry,
    26	        int roomNumber,
    27	        RoomType roomType,
    28	        LocalDate checkIn,
    29	        LocalDate checkOut,
    30	        int nights,
    31	        BigDecimal subtotal,
    32	        BigDecimal discount,
    33	        BigDecimal total,
    34	        String text) {
    35	
    36	    private static final BigDecimal WITHHELD_ISS_RATE = new BigDecimal("0.05");
    37	
    38	    public ReservationReceipt(Reservation reservation, Room room) {
    39	        this(reservation, room, reservation.guest());
    40	    }
    41	
    42	    private ReservationReceipt(Reservation reservation, Room room, Guest guest) {
    43	        this(
    44	                titleFor(guest.identification()),
    45	                reservation.id(),
    46	                guest.name(),
    47	                guest.cpf(),
    48	                guest.companyCnpj(),
    49	                guest.companyName(),
    50	                guest.passport(),
    51	                guest.country(),
    52	                room.number(),
    53	                room.type(),
    54	                reservation.checkIn(),
    55	                reservation.checkOut(),
    56	                reservation.price().nights(),
    57	                reservation.price().subtotal(),
    58	                reservation.price().discount(),
    59	                reservation.price().total(),
    60	                null);
    61	    }
    62	
    63	    /** Fills in the text, which is derived from the other fields. */
    64	    public ReservationReceipt {
    65	        if (text == null) {
    66	            text = render(title, reservationId, guestName, guestCpf, companyCnpj, companyName, guestPassport,
    67	                    guestCountry, roomNumber, roomType, checkIn, checkOut, nights, subtotal, discount, total);
    68	        }
    69	    }
    70	
    71	    private static String titleFor(Identification identification) {
    72	        return switch (identification) {
    73	            case Identification.Cpf cpf -> "Comprovante de reserva";
    74	            case Identification.Company company -> "Fatura de hospedagem";
    75	            case Identification.Passport passport -> "Booking receipt";
    76	        };
    77	    }
    78	
    79	    private static String render(
    80	            String title, long reservationId, String guestName, String cpf, String cnpj, String companyName,
    81	            String passport, String country, int roomNumber, RoomType roomType, LocalDate checkIn,
    82	            LocalDate checkOut, int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    83	        StringBuilder text = new StringBuilder();
    84	        if (passport != null) {
    85	            text.append(title).append(" no. ").append(reservationId).append('\n');
    86	            text.append("Guest: ").append(guestName)
    87	                    .append(" (passport ").append(passport).append(", ").append(country).append(")\n");
    88	            text.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    89	            text.append("Check-in: ").append(TextFormat.englishDate(checkIn))
    90	                    .append(" | Check-out: ").append(TextFormat.englishDate(checkOut))
    91	                    .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append('\n');
    92	            text.append("Nights: ").append(TextFormat.englishMoney(subtotal)).append('\n');
    93	            if (discount.signum() > 0) {
    94	                text.append("Discount: ").append(TextFormat.englishMoney(discount)).append('\n');
    95	            }
    96	            text.append("Total: ").append(TextFormat.englishMoney(total)).append('\n');
    97	            return text.toString();
    98	        }
    99	        text.append(title).append(" nº ").append(reservationId).append('\n');
   100	        if (cnpj != null) {
   101	            text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(cnpj).append(")\n");
   102	            text.append("Hóspede: ").append(guestName).append('\n');
   103	        } else {
   104	            text.append("Hóspede: ").append(guestName).append(" (CPF ").append(cpf).append(")\n");
   105	        }
   106	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
   107	        text.append("Entrada: ").append(TextFormat.date(checkIn))
   108	                .append(" | Saída: ").append(TextFormat.date(checkOut))
   109	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
   110	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
   111	        if (discount.signum() > 0) {
   112	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
   113	        }
   114	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
   115	        if (cnpj != null) {
   116	            BigDecimal iss = PriceCalculator.cents(total.multiply(WITHHELD_ISS_RATE));
   117	            text.append("ISS retido (5%): ").append(TextFormat.money(iss)).append('\n');
   118	        }
   119	        return text.toString();
   120	    }
   121	}
