     3	/** The person who stays. The name and e-mail are always the guest's; the identification varies. */
     4	public record Guest(String name, String email, Identification identification) {
     5	
     6	    public Guest(String name, String email, String cpf) {
     7	        this(name, email, new Identification.Cpf(cpf));
     8	    }
     9	
    10	    public String cpf() {
    11	        return identification instanceof Identification.Cpf cpf ? cpf.number() : null;
    12	    }
